/*
 * A001915  Primes p such that the congruence 2^x == 3 (mod p) is solvable.
 * https://oeis.org/A001915
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, nice
 * Formula:   sieve the primes p; p is a term iff 3 lies in the subgroup
 *            generated by 2 mod p, i.e. 3^ord_p(2) == 1 (mod p) (p = 2
 *            included, p = 3 excluded)
 * Range:     u8 n <= 32, u16 n <= 3771, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   a001915_pw
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/a001915_pw.h"

static uint64_t *a001915_terms = NULL;
static idx_t a001915_cnt = 0;

static void a001915_build(idx_t need) {
    uint64_t limit = 1024;
    while (limit < 64) limit *= 2;
    for (;;) {
        uint32_t *spf = (uint32_t *)calloc((size_t)limit + 1, sizeof(uint32_t));
        uint64_t *t = (uint64_t *)malloc(sizeof(uint64_t) * ((size_t)limit / 2 + 2));
        idx_t c = 0;
        uint64_t i, j;
        for (i = 2; i <= limit; i++) {
            if (spf[i] == 0) {
                for (j = i; j <= limit; j += i)
                    if (spf[j] == 0) spf[j] = (uint32_t)i;
            }
        }
        for (i = 2; i <= limit; i++) {
            uint64_t p, ord, m;
            if (spf[i] != i) continue;
            p = i;
            if (p == 2) { t[c++] = 2; continue; }
            if (p == 3) continue;
            ord = p - 1;
            m = p - 1;
            while (m > 1) {
                uint64_t q = spf[m];
                while (m % q == 0) m /= q;
                while (ord % q == 0 && a001915_pw(2, ord / q, p) == 1) ord /= q;
            }
            if (a001915_pw(3, ord, p) == 1) t[c++] = p;
        }
        free(spf);
        if (c >= need) {
            free(a001915_terms);
            a001915_terms = t;
            a001915_cnt = c;
            return;
        }
        free(t);
        limit *= 2;
    }
}

seq_t a(idx_t n) {
    if (n == 0) n = 1;
    if (n > a001915_cnt) a001915_build(n);
    return (seq_t)a001915_terms[n - 1];
}
